-- ParadiseRP reclassement idempotent du catalogue massif HabboRPbr
SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE parent_id=VALUES(parent_id),caption=VALUES(caption),order_num=VALUES(order_num),visible='1',enabled='1';
DROP TEMPORARY TABLE IF EXISTS paradise_catalog_reorg;
CREATE TEMPORARY TABLE paradise_catalog_reorg (offer_id INT NOT NULL PRIMARY KEY,page_id INT NOT NULL,order_number INT NOT NULL);
UPDATE catalog_items c JOIN paradise_catalog_reorg r ON r.offer_id=c.offer_id SET c.page_id=r.page_id;
DROP TEMPORARY TABLE paradise_catalog_reorg;
COMMIT;
